      fr: ["Superficie : 220 km²", "Hauteur de la cascade : 30 m", "Précipitations annuelles : 120 mm", "Création en tant que parc national : 2009", "Nombre d'espèces de plantes : plus de 100", "Statut de réserve de biosphère de l'UNESCO : 2018"],
