      hu: ["A park 19 négyzetkilométernyi természetes mangroveerdőt véd Abu Dhabi-ban.", "Szinte kizárólag szürke mangrovékból (Avicennia marina) áll.", "A mangrovék négyszer több szenet kötnek meg, mint a trópusi esőerdők.", "Több mint 60 különböző madárfajt figyeltek meg a nemzeti parkban.", "Az erdők természetes bölcsődeként szolgálnak számos helyi halfaj számára.", "A kajakozás a legkörnyezetkímélőbb módja az ökoszisztéma felfedezésének."],
      ro: ["Parcul protejează 19 kilometri pătrați de pădure naturală de mangrove în Abu Dhabi.", "Constă aproape exclusiv din mangrove cenușii (Avicennia marina).", "Mangrovele stochează de până la patru ori mai mult carbon decât pădurile tropicale.", "Peste 60 de specii diferite de păsări au fost observate în parcul național.", "Pădurile servesc ca o pepinieră naturală pentru multe specii locale de pești.", "Caiacul este cea mai ecologică metodă de a explora acest ecosistem."],
      en: ["The park protects 19 square kilometers of natural mangrove forest in Abu Dhabi.", "It consists almost entirely of Grey Mangroves (Avicennia marina).", "Mangroves can sequester up to four times more carbon than tropical forests.", "The area provides a critical habitat for over 60 different bird species.", "The root systems serve as nurseries for local fish and marine organisms.", "Guided kayaking tours are the primary way for visitors to explore the park."],
      es: ["Superficie: 20 km²", "Año de fundación: 2011", "Almacenamiento de CO2: 1.000 t por año", "Número de especies de aves: más de 60", "Longitud de la pasarela de madera: 2 km", "Altura media de los manglares: 5 m"],
      pt: ["Área: 20 km²", "Ano de fundação: 2011", "Armazenamento de CO2: 1.000 t por ano", "Número de espécies de aves: mais de 60", "Comprimento da passarela de madeira: 2 km", "Altura média dos manguezais: 5 m"],
      fr: ["Superficie : 20 km²", "Année de création : 2011", "Stockage de CO2 : 1 000 t par an", "Nombre d'espèces d'oiseaux : plus de 60", "Longueur de la passerelle en bois : 2 km", "Hauteur moyenne des mangroves : 5 m"],
