      hu: ["Abu Dhabi első védett természeti területe, amelyet 1998-ban hoztak létre.", "2013-ban kapta meg a nemzetközi Ramsari vizes élőhely minősítést.", "A főszezonban akár 4000 rózsás flamingó is megfigyelhető a területen.", "A rezervátum területén eddig több mint 250 madárfajt regisztráltak.", "A védett terület kiterjedése pontosan öt négyzetkilométer.", "A régióban elsőként került fel az IUCN természetvédelmi területeinek zöld listájára."],
      ro: ["Prima rezervație naturală din Abu Dhabi, înființată oficial în anul 1998.", "Recunoscută ca zonă umedă de importanță internațională Ramsar în 2013.", "Găzduiește peste 4.000 de flamingo mari în timpul sezonului de vârf.", "Peste 250 de specii de păsări au fost documentate în limitele rezervației.", "Suprafața totală a zonei protejate este de exact cinci kilometri pătrați.", "Este prima zonă din regiune inclusă pe Lista Verde a IUCN."],
      en: ["The first protected area in Abu Dhabi, established in 1998.", "Officially recognized as a Ramsar Wetland of International Importance in 2013.", "Home to more than 4,000 Greater Flamingos during the peak season.", "Over 250 different species of birds have been recorded within the reserve.", "The total area of the protected wetland is exactly five square kilometers.", "First site in the region to be included on the IUCN Green List of Protected Areas."],
      es: ["Superficie: 5 km²", "Año de fundación: 1998", "Estatus Ramsar: 2015", "Número de especies de aves: 260+", "Máximo número de flamencos: 4.000", "Salinidad del agua: 3–10 %"],
      pt: ["Superfície: 5 km²", "Ano de fundação: 1998", "Estatuto Ramsar: 2015", "Número de espécies de aves: 260+", "Número máximo de flamingos: 4.000", "Salinidade da água: 3–10 %"],
      fr: ["Superficie : 5 km²", "Année de fondation : 1998", "Statut Ramsar : 2015", "Nombre d'espèces d'oiseaux : 260+", "Nombre maximal de flamants roses : 4 000", "Salinité de l'eau : 3–10 %"],
