      en: ["The largest unfenced nature reserve in the UAE (spanning about 40 hectares).", "Home to the significant Saruq Al Hadid archaeological site within its borders.", "Over 170 species of birds have been recorded at the man-made Al Qudra Lakes.", "Features an 86-kilometer cycling track known as the Al Qudra Cycling Track.", "Supports the largest concentration of Arabian Oryx in the entire world.", "Host to the prestigious annual Al Marmoom Heritage Festival."],
