      es: ["La palabra 'Love' se puede leer desde el aire en el paisaje.", "Un lugar popular para picnics y atardeceres.", "Hay más de 16.000 árboles y plantas en los alrededores."],
      pt: ["A palavra 'Love' pode ser lida a partir do ar no terreno.", "Um local popular para piqueniques e pores do sol.", "Existem mais de 16.000 árvores e plantas na área."],
