      ro: ["Inaugurat oficial în noiembrie 2018 de către Șeicul Hamdan bin Mohammed.", "Cele două lacuri în formă de inimă sunt vizibile pe imaginile din satelit.", "Peste 16.000 de copaci și mii de flori colorate au fost plantate în jur.", "Face parte din rezervația mai mare Al Marmoom Desert Conservation Reserve.", "Include zone dedicate pentru grătar și trasee de plimbare pe malul apei.", "Găzduiește peste 150 de specii de păsări, inclusiv lebede și rațe sălbatice."],
