    descriptionAdvanced: {
      de: "Der Mushrif National Park in Dubai ist einer der ältesten und flächenmäßig größten Parks der Stadt. Er erstreckt sich über eine Fläche von rund 5,25 Quadratkilometern im Stadtteil Mirdif und bietet eine einzigartige Mischung aus gepflegten Grünanlagen und natürlicher Wüstenlandschaft. Besonders bekannt ist der Park für seine dichten Bestände an einheimischen Ghaf-Bäumen, die zahlreichen Vogelarten wie Eulen und Wiedehopfen einen Lebensraum bieten. Ein Highlight für Familien ist das Global Village innerhalb des Parks, in dem Modelle traditioneller Häuser aus verschiedenen Ländern der Welt im Maßstab nachgebaut sind. Neben Picknickplätzen und Spielplätzen bietet der Park auch moderne Attraktionen wie einen Hochseilgarten und kilometerlange Mountainbike-Strecken. Der Park wurde bereits 1982 eröffnet und dient seitdem als grüne Lunge und wichtiges Naherholungsgebiet für die Einwohner Dubais. Durch seine Lage am Stadtrand bietet er eine willkommene Ruheoase abseits der Wolkenkratzer.",
      hu: "A dubaji Mushrif Nemzeti Park a város egyik legrégebbi és területileg legnagyobb parkja. A Mirdif negyedben elterülő, mintegy 5,25 négyzetkilométeres terület az ápolt zöldfelületek és a természetes sivatagi táj egyedülálló keverékét kínálja. A park különösen ismert őshonos ghaf-fa állományáról, amely számos madárfajnak, például baglyoknak és búbos bankáknak nyújt élőhelyet. A családok számára kiemelt vonzerőt jelent a parkon belüli Global Village, ahol a világ különböző országainak hagyományos házait mutatják be méretarányos modelleken. A piknikezőhelyek és játszóterek mellett a park modern attrakciókat is kínál, mint például kötélpályát és több kilométer hosszú hegyi kerékpáros útvonalakat. A parkot 1982-ben nyitották meg, és azóta Dubaj zöld tüdejeként és fontos szabadidős központjaként szolgál. Városszéli elhelyezkedése révén kellemes pihenőhelyet biztosít a felhőkarcolók világától távol.",
      ro: "Parcul Național Mushrif din Dubai este unul dintre cele mai vechi și mai mari parcuri din oraș ca suprafață. Întinzându-se pe aproximativ 5,25 kilometri pătrați în districtul Mirdif, acesta oferă un amestec unic de zone verzi amenajate și peisaj natural de deșert. Parcul este cunoscut în special pentru populațiile sale dense de arbori Ghaf nativi, care oferă un habitat pentru numeroase specii de păsări, cum ar fi bufnițele și pupăza. Un punct de atracție pentru familii este Satul Global din interiorul parcului, unde sunt reproduse modele la scară ale caselor tradiționale din diferite țări ale lumii. Pe lângă locurile de picnic și de joacă, parcul oferă și atracții moderne, cum ar fi un parc de aventură cu frânghii și kilometri de trasee pentru ciclism montan. Parcul a fost deschis în 1982 și servește de atunci ca plămân verde și zonă importantă de recreere pentru locuitorii din Dubai. Prin locația sa la marginea orașului, oferă o oază de liniște binevenită departe de zgârie-nori.",
      en: "Mushrif National Park in Dubai is one of the city's oldest and largest parks by area. Spanning approximately 5.25 square kilometres in the Mirdif district, it offers a unique blend of manicured green spaces and natural desert landscapes. The park is particularly famous for its dense stands of native Ghaf trees, which provide a habitat for numerous bird species such as owls and hoopoes. A highlight for families is the Global Village within the park, featuring scale models of traditional houses from various countries around the world. In addition to picnic areas and playgrounds, the park offers modern attractions like a high-ropes adventure park and kilometres of mountain biking trails. The park was opened in 1982 and has since served as a green lung and a vital recreational hub for Dubai residents. Its location on the outskirts of the city provides a welcome sanctuary of peace away from the skyscrapers.",
      es: "El Parque Nacional Mushrif en Dubái, EAU, es un parque urbano de 3,5 kilómetros cuadrados inaugurado en 2011. Ofrece árboles nativos y senderos para caminar. El parque cuenta con áreas de picnic, un parque infantil de aventuras y el Mushrif Park Centre. Hay un carril bici de 5 kilómetros. El parque es un área de recreación importante y alberga diversas especies animales como zorros del desierto y lagartos. La entrada es de pago. El parque es conocido por sus árboles Ghaf, que pueden vivir hasta 80 años.",
      pt: "O Parque Nacional Mushrif em Dubai, EAU, é um parque urbano de 3,5 quilômetros quadrados inaugurado em 2011. Oferece árvores nativas e trilhas para caminhada. O parque possui áreas de piquenique, um parquinho de aventuras e o Mushrif Park Centre. Há uma ciclovia de 5 quilômetros. O parque é uma importante área de lazer e abriga diversas espécies animais, como raposas do deserto e lagartos. A entrada é paga. O parque é conhecido por suas árvores Ghaf, que podem viver até 80 anos.",
      fr: "Le parc national Mushrif à Dubaï, aux EAU, est un parc urbain de 3,5 kilomètres carrés inauguré en 2011. Il offre des arbres indigènes et des sentiers de randonnée. Le parc dispose d'aires de pique-nique, d'une aire de jeux d'aventure et du Mushrif Park Centre. Il y a une piste cyclable de 5 kilomètres. Le parc est une zone de loisirs importante et abrite diverses espèces animales comme les renards du désert et les lézards. L'entrée est payante. Le parc est connu pour ses arbres Ghaf, qui peuvent vivre jusqu'à 80 ans.",
    },
